package server.bots;
import client.Character;import scripting.event.EventManager;import server.expeditions.*;import net.server.world.Party;import org.junit.jupiter.api.Test;import javax.script.*;import java.nio.file.*;import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;
class BotHorntailNpcTest {
 public static class Conversation {public final Character player=mock(Character.class);public final EventManager event=mock(EventManager.class);public String menu="",answer="";public Character getPlayer(){return player;}public EventManager getEventManager(String n){return event;}public Expedition getExpedition(ExpeditionType t){return null;}public boolean isUsingOldPqNpcStyle(){return false;}public int getMapId(){return 240050000;}public Party getParty(){return null;}public int createExpedition(ExpeditionType t){return 0;}public void sendSimple(String s){menu=s;}public void sendOk(String s){answer=s;}public void dispose(){}}
 private ScriptEngine open(Conversation cm,String id)throws Exception{when(cm.player.getLevel()).thenReturn(150);var e=new ScriptEngineManager().getEngineByName("graal.js");var b=e.getBindings(ScriptContext.ENGINE_SCOPE);b.put("polyglot.js.allowHostAccess",true);b.put("polyglot.js.allowHostClassLookup",true);b.put("cm",cm);e.eval(Files.readString(Path.of("scripts/npc/"+id+".js")));e.eval("start();");return e;}
 @Test void trialNpcKeepsNormalEntryAndAddsCrewMenu()throws Exception{var c=new Conversation();try(var crews=mockStatic(BotHorntailCompanions.class)){crews.when(()->BotHorntailCompanions.assemble(c.player)).thenReturn("ready");var e=open(c,"2083001");assertTrue(c.menu.contains("trial grounds"));assertTrue(c.menu.contains("BotPQ Menu"));e.eval("action(1,4,900);");assertEquals("ready",c.answer);}}
 @Test void trialNpcNormalEntryStillRequiresParty()throws Exception{var c=new Conversation();var e=open(c,"2083001");e.eval("action(1,4,0);");assertTrue(c.answer.contains("only if you are in a party"));}
 @Test void expeditionNpcKeepsNormalCreation()throws Exception{var c=new Conversation();var e=open(c,"2083004");assertTrue(c.menu.contains("Lets get this going"));assertTrue(c.menu.contains("BotPQ Menu"));e.eval("action(1,4,1);");assertTrue(c.answer.contains("has been created"));}
 @Test void expeditionNpcDismissesOnlyAssignedCrew()throws Exception{var c=new Conversation();try(var crews=mockStatic(BotHorntailCompanions.class)){crews.when(()->BotHorntailCompanions.release(c.player)).thenReturn("dismissed");var e=open(c,"2083004");e.eval("action(1,4,901);");assertEquals("dismissed",c.answer);crews.verify(()->BotHorntailCompanions.release(c.player));}}
}
